using System;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Text;using System.Text.RegularExpressions;
namespace DragonCompanion {
public sealed class ClaudeEntry {public string Id,Title,Effort,Path;public bool Ultra;public override string ToString(){return Title;}}
public static class ClaudeForms {
 public static readonly string[] Keys={"chibi","medium","full","xhigh","max","ultra"};public static readonly string[] Labels={"待机 · Low","清醒 · Medium","觉醒 · High","超凡 · Extra","思维之日 · Max","日蚀 · Ultracode"};
 public static int Index(string effort,bool ultra){if(ultra)return 5;switch(effort){case "low":return 0;case "medium":return 1;case "high":return 2;case "xhigh":case "extra":return 3;case "max":return 4;default:return -1;}}
}
// FileAccess.Read + shared handles only. No IPC, request proxy, settings writes, or app patching.
public sealed class ClaudeSource {
 public readonly string DataRoot;public string FocusId{get;private set;}public bool FocusKnown{get;private set;}public string Hint{get;private set;}public List<ClaudeEntry> Entries=new List<ClaudeEntry>();string partial="";long position;DateTime nextScan=DateTime.MinValue;string host="";
 public ClaudeSource(string dataRoot){DataRoot=dataRoot;Hint="等待 Claude";}
 public static bool ParseFocus(string line,out string id){id=null;if(line==null||line.Length>8192)return false;var m=Regex.Match(line,@"\[CCD\] LocalSessions\.setFocusedSession: sessionId=(null|local_[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})(?:\s|$)");if(!m.Success)return line.Contains("[CCD] LocalSessions.setFocusedSession:");if(m.Groups[1].Value!="null")id=m.Groups[1].Value;return true;}
 public static ClaudeEntry ParseMetadata(string text,string path){var d=Json.Decode(text);string id=Json.Str(d,"sessionId");if(id==null||!Regex.IsMatch(id,@"^local_[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")||true.Equals(Json.Get(d,"isArchived")))return null;string title=Json.Str(d,"title")??"未命名聊天";var settings=Json.Obj(d,"sessionSettings");return new ClaudeEntry{Id=id,Title=title.Replace("\r"," ").Replace("\n"," "),Effort=Json.Str(d,"effort"),Ultra=true.Equals(Json.Get(settings,"ultracode")),Path=path};}
 static string ReadShared(string file){using(var f=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(f.Length>1048576)throw new IOException("Metadata size limit");using(var reader=new StreamReader(f,Encoding.UTF8))return reader.ReadToEnd();}}
 public void Update(string hostId,DateTime startedUtc){if(host!=hostId){host=hostId;position=0;partial="";FocusId=null;FocusKnown=false;nextScan=DateTime.MinValue;}if(hostId==""){FocusId=null;FocusKnown=false;Hint="等待 Claude";return;}
  try {string log=System.IO.Path.Combine(DataRoot,"logs","main.log");using(var f=new FileStream(log,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(f.Length<position){position=0;partial="";FocusKnown=false;FocusId=null;}int cap=position==0?2097152:131072;if(f.Length-position>cap){position=f.Length-cap;partial="";FocusKnown=false;FocusId=null;}f.Position=position;var buffer=new byte[(int)Math.Min(cap,f.Length-position)];int n=f.Read(buffer,0,buffer.Length);position+=n;string all=partial+Encoding.UTF8.GetString(buffer,0,n);int end=all.LastIndexOf('\n');if(end>=0){partial=all.Substring(end+1);foreach(string line in all.Substring(0,end).Split('\n')){string id;if(!ParseFocus(line,out id))continue;DateTime time;if(line.Length<19||!DateTime.TryParseExact(line.Substring(0,19),"yyyy-MM-dd HH:mm:ss",CultureInfo.InvariantCulture,DateTimeStyles.AssumeLocal,out time)||time.ToUniversalTime().AddSeconds(5)<startedUtc)continue;if(FocusId!=id)nextScan=DateTime.MinValue;FocusId=id;FocusKnown=true;}}else partial=all.Length<8192?all:"";}
   if(DateTime.UtcNow>=nextScan){nextScan=DateTime.UtcNow.AddSeconds(2);var entries=new List<ClaudeEntry>();foreach(string folderName in new[]{"claude-code-sessions","local-agent-mode-sessions"}){string folder=System.IO.Path.Combine(DataRoot,folderName);if(Directory.Exists(folder))foreach(string file in Directory.EnumerateFiles(folder,"local_*.json",SearchOption.AllDirectories).Take(4096)){try{var x=ParseMetadata(ReadShared(file),file);if(x!=null)entries.Add(x);}catch{}}}Entries=entries.GroupBy(e=>e.Id).Select(g=>g.First()).OrderBy(e=>e.Title).ToList();}Hint=FocusKnown?(FocusId==null?"新聊天尚无档位数据 · 等待发送或选择聊天":"已识别聚焦聊天"):"等待选择聊天";
  }catch{FocusKnown=false;FocusId=null;Hint="Claude 状态不可读 · 等待兼容状态";}}
 public ClaudeEntry ReadSelected(string id){var known=Entries.Find(e=>e.Id==id);if(known==null)return null;try{return ParseMetadata(ReadShared(known.Path),known.Path);}catch{return null;}}
}
public sealed class ClaudeHost {
 [DllImport("user32.dll")]static extern bool IsIconic(IntPtr h);[DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr h);
 public string Identity="";public bool Visible;public DateTime StartedUtc;
 public static ClaudeHost Scan(){var h=new ClaudeHost();try{foreach(var p in Process.GetProcessesByName("claude")){using(p){try{if(p.MainWindowHandle==IntPtr.Zero||p.MainModule.FileName.IndexOf("WindowsApps\\Claude_",StringComparison.OrdinalIgnoreCase)<0)continue;h.Identity=p.Id+"/"+p.MainModule.FileName;h.StartedUtc=p.StartTime.ToUniversalTime();h.Visible=IsWindowVisible(p.MainWindowHandle)&&!IsIconic(p.MainWindowHandle);return h;}catch{}}}}catch{}return h;}
}
}
